def normalize_catalog_and_designs(apps, schema_editor):
    Vehicle = apps.get_model('garage', 'Vehicle')
    CustomDesign = apps.get_model('garage', 'CustomDesign')

    # Bring the original sample catalog into the same category keys used by
    # the new car and bike routes, while retaining existing vehicle records.
    for vehicle in Vehicle.objects.all():
        category = str(vehicle.category).lower()
        if category in {'car', 'bike'}:
            vehicle.category = category
            vehicle.save(update_fields=['category'])

    # Keep the original Yamaha record and its uploaded image/design links.
    yamaha = Vehicle.objects.filter(category='bike').order_by('id').first()
    if yamaha:
        yamaha.company = 'Yamaha'
        yamaha.name = 'R1'
        yamaha.save(update_fields=['company', 'name'])

    catalog = [
        ('car', 'BMW', 'M4', 'https://images.unsplash.com/photo-1555215695-3004980ad54e?w=900'),
        ('car', 'Mercedes-Benz', 'AMG C 63', 'https://images.unsplash.com/photo-1618843479313-40f8afb4b4d8?w=900'),
        ('car', 'Audi', 'RS 5', 'https://images.unsplash.com/photo-1542362567-b07e54358753?w=900'),
        ('bike', 'KTM', '390 Duke', 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?w=900'),
        ('bike', 'Royal Enfield', 'Continental GT', 'https://images.unsplash.com/photo-1558980394-0c9b4a9b4f5b?w=900'),
    ]
    for category, company, name, image_url in catalog:
        Vehicle.objects.get_or_create(
            category=category,
            company=company,
            name=name,
            defaults={'image_url': image_url},
        )
    for vehicle in Vehicle.objects.filter(image_url=''):
        for category, company, name, image_url in catalog:
            if (vehicle.category, vehicle.company, vehicle.name) == (category, company, name):
                vehicle.image_url = image_url
                vehicle.save(update_fields=['image_url'])
                break

    # Translate the original free-text selections to equivalent saved options.
    CustomDesign.objects.filter(color__iexact='black').update(color='#171717')
    CustomDesign.objects.filter(wheels__iexact='2').update(wheels='street')
    CustomDesign.objects.filter(spoiler__iexact='top one').update(spoiler='gt')


